async function fetchWithRetry(url, attempts = 3) {
  try {
    const res = await fetch(url);
    if (!res.ok) throw new Error('bad status ' + res.status);
    return res.json();
  } catch (err) {
    if (attempts > 1) {
      await new Promise(r => setTimeout(r, 200));
      fetchWithRetry(url, attempts - 1);
    } else {
      throw err;
    }
  }
}
